async fn delivered_groups(
    adapter: &NostrTransportAdapter,
    expected: usize,
    wait: Duration,
) -> HashSet<Vec<u8>> {
    const IDLE: Duration = Duration::from_millis(1_500);
    let mut delivered = HashSet::new();
    let deadline = tokio::time::Instant::now() + wait;
    let diagnostic_start = deadline - wait;
    let mut diagnostic_exit = 0u8; // expected count reached
    let mut diagnostic_receives = 0u64;
    let mut diagnostic_unhinted = 0u64;
    let mut diagnostic_known = true;
    while delivered.len() < expected {
        let next = deadline.min(tokio::time::Instant::now() + IDLE);
        match tokio::time::timeout_at(next, adapter.receive()).await {
            Ok(Ok(Some(delivery))) => {
                if let Some(count) = diagnostic_receives.checked_add(1) {
                    diagnostic_receives = count;
                } else {
                    diagnostic_known = false;
                }
                if let Some(group) = delivery.group_id_hint {
                    delivered.insert(group.as_slice().to_vec());
                } else if let Some(count) = diagnostic_unhinted.checked_add(1) {
                    diagnostic_unhinted = count;
                } else {
                    diagnostic_known = false;
                }
            }
            Err(_) => {
                diagnostic_exit = if next == deadline { 1 } else { 2 };
                break;
            }
            Ok(Ok(None)) => {
                diagnostic_exit = 3;
                break;
            }
            Ok(Err(_)) => {
                diagnostic_exit = 4;
                break;
            }
        }
    }
    eprintln!(
        "transport-delivery-exit known={} exit={} delivered={} receives={} unhinted={} elapsed_us={}",
        diagnostic_known,
        diagnostic_exit,
        delivered.len(),
        diagnostic_receives,
        diagnostic_unhinted,
        diagnostic_start.elapsed().as_micros()
    );
    delivered
}
